INSERT INTO `history_human` VALUES ('周恩来','1898年3月5日—1976年1月8日','http://124.77.173.173:9000/ar-travel/resource/zhou_enlai2.jpg','周恩来，字翔宇，原籍浙江绍兴，1898年3月5日生于江苏淮安。伟大的无产阶级革命家、政治家、军事家、外交家，中国共产党和中华人民共和国的主要领导人之一。',1),('毛泽东','1893年12月26日—1976年9月9日','http://124.77.173.173:9000/ar-travel/resource/mao_zedong2.jpg','毛泽东，字润之，笔名子任。湖南湘潭人。中国人民的领袖，伟大的马克思主义者，伟大的无产阶级革命家、战略家、理论家，中国共产党、中国人民解放军和中华人民共和国的主要缔造者和领导人。',3),('朱德','1886年12月1日—1976年7月6日','http://124.77.173.173:9000/ar-travel/resource/zhu_de.jpg','朱德，字玉阶，原名朱代珍，四川仪陇人。伟大的马克思主义者，伟大的无产阶级革命家、政治家、军事家，中国人民解放军的主要缔造者之一，中华人民共和国的开国元勋，十大元帅之首。',11),('彭德怀','1898年10月24日—1974年11月29日','http://124.77.173.173:9000/ar-travel/resource/peng_dehuai.jpg','彭德怀，原名彭清宗，湖南湘潭人。伟大的无产阶级革命家、军事家、政治家，中国人民解放军的缔造者之一，中华人民共和国的开国元勋，十大元帅之一。',12),('刘伯承','1892年12月4日—1986年10月7日','http://124.77.173.173:9000/ar-travel/resource/liu_bocheng.jpg','刘伯承，原名刘明昭，字伯承，四川开县人。伟大的无产阶级革命家、军事家，中国人民解放军的缔造者之一，中华人民共和国的开国元勋，十大元帅之一。',14),('贺龙','1896年3月22日—1969年6月9日','http://124.77.173.173:9000/ar-travel/resource/he_long.jpg','贺龙，原名贺文常，字云卿，湖南桑植人。伟大的无产阶级革命家、军事家，中国人民解放军的缔造者之一，中华人民共和国的开国元勋，十大元帅之一。',15),('陈毅','1901年8月26日—1972年1月6日','http://124.77.173.173:9000/ar-travel/resource/chen_yi.jpg','陈毅，字仲弘，四川乐至人。伟大的无产阶级革命家、军事家、外交家，中国人民解放军的缔造者之一，中华人民共和国的开国元勋，十大元帅之一。',16),('罗荣桓','1902年11月26日—1963年12月16日','http://124.77.173.173:9000/ar-travel/resource/luo_ronghuan.jpg','罗荣桓，原名罗慎镇，字雅怀，湖南衡山人。伟大的无产阶级革命家、军事家，中国人民解放军政治工作的奠基人，中华人民共和国的开国元勋，十大元帅之一。',17),('徐向前','1901年11月8日—1990年9月21日','http://124.77.173.173:9000/ar-travel/resource/xu_xiangqian.jpg','徐向前，原名徐象谦，字子敬，山西五台人。伟大的无产阶级革命家、军事家，中国人民解放军的缔造者之一，中华人民共和国的开国元勋，十大元帅之一。',18),('聂荣臻','1899年12月29日—1992年5月14日','http://124.77.173.173:9000/ar-travel/resource/nie_rongzhen.jpg','聂荣臻，字福骈，四川江津人。伟大的无产阶级革命家、军事家，中国人民解放军的缔造者之一，中华人民共和国的开国元勋，十大元帅之一。',19),('叶剑英','1897年4月28日—1986年10月22日','http://124.77.173.173:9000/ar-travel/resource/ye_jianying.jpg','叶剑英，原名叶宜伟，字沧白，广东梅县人。伟大的无产阶级革命家、政治家、军事家，中国人民解放军的缔造者之一，中华人民共和国的开国元勋，十大元帅之一。',20);
/*!40000 ALTER TABLE `history_human` ENABLE KEYS */;
UNLOCK TABLES;

