INSERT INTO `travel_module_detail` VALUES (819723818527625216,847162,'山西铭贤学校旧址',NULL,NULL,'https://ar-travel-file.1jiaohu.com/resource/20260610/d18d6024be6749f18fa5208b5cff939c.jpg','','https://content-vintage-includes-night.trycloudflare.com/img/mingxian_audio.wav','',NULL,'<p style=\"text-align:center;\"><img src=\"https://ar-travel.1jiaohu.com/files/20250929/a998eb72-782c-4a5b-a575-fa61ceb1fbe5ccc33bdf0cd84f5080726134406e0f3c.gif\" width=\"30%\"/><br/><br/></p><p style=\"text-align:center;\">山西铭贤学校旧址</p><p><img src=\"https://ar-travel.1jiaohu.com/files/20250929/d4156e0b-fbf8-4baa-8947-58c0270a4f94%E5%B1%B1%E8%A5%BF%E9%93%AD%E8%B4%A4%E5%AD%A6%E6%A0%A1.jpg\" data-extentions-extra-ocr-id=\"43d531f5c14e129461062a844ac2d031\" width=\"100%\"/></p><p>清<a href=\"https://baike.baidu.com/item/%E5%AE%A3%E7%BB%9F/1523933?fromModule=lemma_inlink\" target=\"_blank\">宣统</a>元年（1909年），孔祥熙将创办的铭贤学校搬迁至山西铭贤学校旧址，随学校的发展扩大，校舍陆续增建形成现有规模。民国二十一年（1932年）学校南迁，更名为铭贤学院。</p><p>1950年，铭贤学院迁回山西铭贤学校旧址。</p><p>1951年，山西铭贤学校被政府接收，更名为山西农学院。</p><p>1979年，山西农学院更名为山西农业大学。</p><p><br/></p><p><img src=\"https://ar-travel.1jiaohu.com/files/20250929/a55f6333-5c3e-4d6b-be3f-37f4b74a3e5ewps.png\" data-extentions-extra-ocr-id=\"bc57d408d846962bb47a5a2f1eea350d\"/>《亮剑》中南京军事学院一太谷<a target=\"_blank\" href=\"https://ent.163.com/keywords/5/7/5c71897f/1.html\">山西</a>农业大学</p><p><br/></p><p><img src=\"https://ar-travel.1jiaohu.com/files/20250929/5578d578-b145-4512-8ac2-399e53a5eb43wps%20(1).png\" data-extentions-extra-ocr-id=\"4e31cc9a68c6daeaf6aca8b50b87e48a\"/>《亮剑》中南京军事学院一太谷山西农业大学</p><p><br/></p><p><img src=\"https://ar-travel.1jiaohu.com/files/20250929/6893a329-07ec-4276-baef-9649bc965c2bwps%20(2).png\" data-extentions-extra-ocr-id=\"37e144b6fb23b672326bee0a476262e5\"/>《亮剑》中南京军事学院一太谷山西农业大学</p>',1,1,'2026-06-10 16:54:17','37.425856,112.582578',NULL,NULL,0,NULL,0,0,NULL,1,'https://ar-travel-file.1jiaohu.com/resource/20260610/b36bd62ed70340ae9a9acdb9df1294ec.jpg','','',NULL,NULL,'Oberlin Shansi Memorial School Old Site',NULL,NULL,NULL,NULL,'<p><br></p>','1',0,0,'2026-06-10 16:54:16',0,'','',NULL,NULL),(819725592235872256,847162,'韩氏楼',NULL,NULL,'https://ar-travel-file.1jiaohu.com/resource/20260610/571efc98d49549dea908da666de2fe0a.png','','','',NULL,'<p>1924年落成的韩氏楼，是铭贤学校时期建成的主要建筑物之一，由美藉人氏韩明卫（Hemingway）家族捐款兴建。</p><p>孔祥熙在美国欧柏林大学求学时与美籍学生D.W.H.Hemingway相识交好，并为之起了个中国名字韩明卫。1903年韩明卫携新婚妻子韩美瑞到中国传教。1904年来到太谷，在孟家花园办起仁术医院（1901年办理教案时，孟家花园被据为教会财产），自任院长。1909年为支持铭贤学堂扩大办学规模，韩明卫将孟家花园换让给铭贤学堂。1924年建成韩氏楼，据《铭贤廿週纪念》标注：韩明卫之弟为纪念其母捐建韩氏楼，实则是韩氏家族共建。</p><p>韩氏楼位于嘉桂科学楼西南方，建筑面积1026平方米。古式建筑，砖木结构，青瓦大屋顶，十二角飞檐。东、中、西三处楼门均向北开启。中门与东西门之间的墙上各镶嵌一黑色石块，上刻有“韩氏纪念”和 “HEMINGWAYMEMORIAL1924”字样。屋内为地下一层，地上两层，楼梯、地面全为实木结构，居室全部向阳，北侧为入室通道。铭贤时期，地下一层为供暖、供热水和洗浴处，地上二层居室用作男生宿舍。1951年9月改称第一学生宿舍，后改为单身教职工宿舍和研究生宿舍。</p><p><br/></p><p style=\"text-align:center;\"><img src=\"https://ar-travel.1jiaohu.com/files/20250929/f7edf0db-7b0b-4d72-8cb6-52ce6c520bc9%E9%9F%A9%E6%B0%8F%E6%A5%BC%20(2).png\" data-extentions-extra-ocr-id=\"1de9b28daba3609395a3a9b7912f3616\"/><img src=\"https://ar-travel.1jiaohu.com/files/20250929/92367410-5358-4a89-96e4-b9c513bcfdd9%E9%9F%A9%E6%B0%8F%E6%A5%BC%20(3).png\" data-extentions-extra-ocr-id=\"f12929b7b49e9a85970a153a2da785db\"/></p>',1,1,'2026-06-10 17:01:20','37.424698,112.5820',NULL,NULL,0,NULL,0,0,'138888888',1,'https://ar-travel-file.1jiaohu.com/resource/20260610/fc3aadc692584aa68829aa598ba6c4f8.png','','山西农业大学','全天',NULL,'The Han Building',NULL,NULL,'免费',NULL,'<p><br></p>',NULL,0,0,'2026-06-10 17:01:19',0,'','',NULL,NULL),(819726131627560960,847162,'亭兰图书馆',NULL,NULL,'https://ar-travel-file.1jiaohu.com/resource/20260610/4b7cd7f564be47378faf1842e41cde63.png','','','',NULL,'<p>1936年间先后竣工落成的亭兰图书馆、嘉桂科学楼，是铭贤学校时期建成的主要建筑物，由孔祥熙及其夫人宋霭龄于1935年7月为纪念双方父母而筹建。</p><p>亭兰图书馆和嘉桂科学楼各取孔祥熙和宋霭龄父母名字中的二字命名。著名书法家赵铁山亲书其名。当年由我校果树专家贾麟厚教授在两楼背面栽植的十几株加拿大毛白杨，至今己成参天大树。楼与大树相辉映，更显历史的厚重感。</p><p>此二楼主体结构由美国建筑设计师墨菲（HenryKilamMurphy）设计，天津基泰工程公司、天津营造公司补充画图并承建，为中西合璧风格（外观是中式，但内部构造却是西式）。两楼建筑面积都为1382平方米 （其中地下室各为309平米），总投资19.4万元。</p><p>两楼均为三层建筑，地上两层，地下一层，顶上有四面开启洞窗的隔热跃层。建筑用料为青砖、石料、水泥、木材。外墙以五层（其中亭兰外露四层）条型剁石、四层水泥预制块与多层青砖垒起。四壁开设工字型连接的方格窗户，上下窗口间有仿大理石彩墙相隔。室内地板、楼梯、扶手全用精心磨制的钢骨水泥注成。两楼地下室有供暖间、储存室、卫生间（配有座式马桶）等。</p><p>两楼楼门抱厦均建在五级石基（其中亭兰外露四层）上，双柱上端与飞檐下部雕刻着“瓶”、“鼎”及 “香炉”等，寓意平等与香火旺盛；又有海马、水壶，红色门柱以示水火相济。两楼门分别向西、向东开启，遥相对峙，意为“门当户对”。屋顶由木构架支承，形成中国建筑特有的曲面大屋顶。顶面用彩色琉璃瓦料铺成。众多彩色吻兽立于屋脊，有“大吻”“重兽”“戗兽”“合角吻兽”；在 “重兽”与“戗兽”前还有多处五个一队的“仙人走兽”，在这些走兽前有一个骑着似凤似鸡的领队，俗称“仙人”。梁枋斗栱彩绘醒目，八角飞檐湾曲高翘，有如翚鸟展翅高飞。其等级有似古代皇家大院中六宫的建筑风格。真乃极尽辉煌壮丽、美轮美奂之能事，这在晋中乡村甚至县城众多官商大院中也属少见。有道是：“剁石青砖大屋顶，中西合璧出茂工。内室精装取西法，屋顶仙兽袭六宫。孔宋儿女争高下，嘉桂亭兰各西东。家事逸闻成往趣，图书科学久对门。经风沐雨八十代，华屋檐下满燕影”。</p><p>亭兰图书馆，取孔祥熙父亲孔和亭的“亭”字和母亲庞玉兰的“兰”字命名。铭贤时期第一层为纪念室、办公室、编目室、阅报室及书库；第二层为阅览室及书库。书库上下可容书10万余册，阅览室可容二百余人同时阅览。为防火，楼内地板、楼梯踏步及栏杆均为水磨石材质，库内书架全部为铁架。阅览室屋内装设无影灯，光线明亮而柔和，不刺眼。桌椅为核桃木制，光滑细致。椅子腿下有橡皮垫，即使有人拖动也不会发出噪音干扰他人。两座图书台，为红木所制，整体为圆形，曲线如人背，设计非常人性化，坐着很舒适。室内备有各种书报杂志，可供读者自由阅览。目录分多种类型编排，方便学生按照书名、作者姓名、出版书店等方式查询，查询方法由北京请来的图书专家编制。图书功能一直延续至今。</p><p><br/></p><p data-we-empty-p=\"\" style=\"text-align:center;\"><img src=\"https://ar-travel-file.1jiaohu.com/resource/20260610/4444724780ce47c59e920c3464031d66.png\" style=\"max-width:100%;\" contenteditable=\"false\" data-extentions-extra-ocr-id=\"a4ae48d4d0f7a5685fae06fa77337953\"/></p>',1,1,'2026-06-10 17:03:28','37.42205,112.58571',NULL,NULL,0,NULL,0,0,NULL,1,'https://ar-travel-file.1jiaohu.com/resource/20260610/9cb1b909ddfd4c1fa46d6289f01a53e0.png','',NULL,NULL,NULL,'Tinglan Library',NULL,NULL,NULL,NULL,'',NULL,0,0,'2026-06-10 17:03:28',0,NULL,NULL,NULL,NULL),(819726611355275264,847162,'嘉桂科学楼',NULL,NULL,'https://ar-travel-file.1jiaohu.com/resource/20260610/51ffe00764924e60b0274bed24f978d3.png','','','',NULL,'<p>嘉桂科学楼，取宋霭龄父亲宋嘉树的“嘉”字和母亲倪桂珍的“桂”字命名。铭贤时期第一层为物理实验室、生物实验室、仪器室、材料室、教室及教员室等；第二层为化学实验室、标本室、天平室、储存室、教室及教员室等。实验室仪器设备精良齐全，可供十几人同时实验。生物标本种类较多。各科的教室与实验室相通，取用方便。1951年以来曾为实验室、教室、图书室，及人事处、档案馆、学报、新农村发展研究院等办公处。</p><p><br/></p><p><img src=\"https://ar-travel.1jiaohu.com/files/20250929/57e0159e-cf28-4c48-9dbf-2368c2354fb4%E5%98%89%E6%A1%82%E7%A7%91%E5%AD%A6%E6%A5%BC1.png\" data-extentions-extra-ocr-id=\"b5a101869139c7e014866e3325d2dfe9\"/></p>',1,1,'2026-06-10 17:05:23','37.42493,112.5827',NULL,NULL,0,NULL,0,0,NULL,1,'https://ar-travel-file.1jiaohu.com/resource/20260610/79498353e91d4b25944e41220f964b33.png','','铭贤南路1号',NULL,NULL,'Jia Gui Science Building',NULL,NULL,NULL,NULL,'',NULL,0,0,'2026-06-10 17:05:22',0,NULL,NULL,NULL,NULL),(819727024129314816,847162,'山西农业大学图书馆大楼',NULL,NULL,'https://ar-travel-file.1jiaohu.com/resource/20260610/c6ef9a1f25034d59b28e601ac8a6b030.png','','','',NULL,'<p>山西农业大学的图书馆大楼是学校的重要设施之一，具有丰富的藏书和现代化的设施。山西农业大学的图书馆大楼不仅是学校的重要学术资源中心，也是校园文化建设的重要组成部分。</p><p><br/></p><p><img src=\"https://ar-travel-file.1jiaohu.com/resource/20260610/23f0df7e344c4ea892d228f20a52add1.png\" style=\"max-width:100%;\" contenteditable=\"false\" data-extentions-extra-ocr-id=\"642aa12f2dd4424679c4ec97b71d5b4b\"/></p>',1,1,'2026-06-10 17:07:01','37.42403,112.5805',NULL,NULL,0,NULL,0,0,NULL,1,'https://ar-travel-file.1jiaohu.com/resource/20260610/0cae1aaadca348de8427946e0293a0f5.png','','山西农业大学图书馆大楼',NULL,NULL,'Shanxi Agricultural University Library',NULL,NULL,NULL,NULL,'',NULL,0,0,'2026-06-10 17:07:00',0,NULL,NULL,NULL,NULL),(819727518461595648,847162,'山西农业大学19号学士公寓',NULL,NULL,'https://ar-travel-file.1jiaohu.com/resource/20260610/54c13dce495b4c7e9b1ad52452401db9.png','','','',NULL,'<p>我校的学生公寓设施一流,室内配有书桌、书架、电话，公寓楼周围绿地如茵、树木掩映、鸟语花香、环境优美。学生饮食服务中心既有大众化的饮食，还有各种各样的风味小吃，能满足各类学生不同的口味和消费水，在省内外高校享有盛誉。</p><p><br/></p><p><img src=\"https://ar-travel-file.1jiaohu.com/resource/20260610/43e0d2814177437b82462d6c4c757b25.png\" style=\"max-width:100%;\" contenteditable=\"false\" data-extentions-extra-ocr-id=\"d186470664e98aaa390ca97d41e4ee82\"/></p>',1,1,'2026-06-10 17:08:59','37.425,112.586',NULL,NULL,0,NULL,0,0,NULL,2,'https://ar-travel-file.1jiaohu.com/resource/20260610/f037325e092b493eb31135542494a7ca.png','',NULL,NULL,NULL,'No.19 Student Apartment',NULL,NULL,NULL,NULL,'',NULL,0,0,'2026-06-10 17:08:58',0,NULL,NULL,NULL,NULL),(819728097422348288,847162,'山西农业大学铭贤学校旧址',NULL,NULL,'https://ar-travel-file.1jiaohu.com/resource/20260610/84446dfe854d492d83a527e79200d99b.jpg','','','',NULL,'<p>山西铭贤学校旧址，原为太谷望族孟氏的别墅，又称孟家花园，位于山西省晋中市<a href=\"https://baike.baidu.com/item/%E5%A4%AA%E8%B0%B7%E5%8C%BA/24190200?fromModule=lemma_inlink\" target=\"_blank\">太谷区</a>候城乡杨家庄村西，始建于清中期。<sup>&nbsp;<em></em></sup></p><p>山西铭贤学校旧址包括孟家花园、教学建筑和宿舍别墅群三个部分。<sup>&nbsp;[2]<em></em></sup>孟家花园，也称“孟氏园”，现存建筑占地面积南北长约80米，东西宽约100米，总面积约8000平方米，分东、中、西三院。东院为两进院落；中院（祀神区）系四合院；西院（寝室及书斋区）是三进院落<sup>&nbsp;[3]<em></em></sup>；教学建筑包括杭氏楼、田氏楼、韩氏楼、亭兰图书馆和嘉桂科学楼；宿舍别墅群，为学生宿舍、外教宿舍，现存16栋，均为二层砖构。<sup>&nbsp;[2]<em></em></sup>山西铭贤学校旧址为完整的旧址遗存，呈现出从清代私家园林到中西文化结合的现代教学设施的巨大变化，展现了清末民国时期中国教育变革的重要发展历程。旧址承载的大量历史信息，为研究北方私家园林、中西文化交流、建筑艺术等提供了实证。</p><p>2013年3月5日，山西铭贤学校旧址被中华人民共和国国务院公布为<a href=\"https://baike.baidu.com/item/%E7%AC%AC%E4%B8%83%E6%89%B9%E5%85%A8%E5%9B%BD%E9%87%8D%E7%82%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D/3525703?fromModule=lemma_inlink\" target=\"_blank\">第七批全国重点文物保护单位</a>。<sup>&nbsp;</sup></p><p><sup><br/></sup></p><p><img src=\"https://ar-travel-file.1jiaohu.com/resource/20260610/508a342eb0fa41b8af8f354823b0e579.jpg\" style=\"max-width:100%;\" contenteditable=\"false\" data-extentions-extra-ocr-id=\"6d2e539c5bfd1fd6504c394a279873d2\"/></p>',1,1,'2026-06-10 17:11:17','37.423875,112.582225',NULL,NULL,0,NULL,0,0,NULL,1,'https://ar-travel-file.1jiaohu.com/resource/20260610/eb27494224c041a394afb923b6e129e5.jpg','',NULL,NULL,NULL,'Oberlin Shansi Memorial School',NULL,NULL,NULL,NULL,'',NULL,0,0,'2026-06-10 17:11:16',0,NULL,NULL,NULL,NULL),(819728677184212992,847162,'崇圣楼',NULL,NULL,'https://ar-travel-file.1jiaohu.com/resource/20260610/e8f8d5130b6c461881d07c0467739e70.jpg','','','',NULL,'',1,1,'2026-06-10 17:13:35','37.437060,112.581633',NULL,NULL,0,NULL,0,0,NULL,2,'https://ar-travel-file.1jiaohu.com/resource/20260610/6c850421fca64195b5c968bef6b648e4.jpg','',NULL,NULL,NULL,'Chongsheng Building',NULL,NULL,NULL,NULL,'',NULL,0,0,'2026-06-10 17:13:35',0,NULL,NULL,NULL,NULL),(819732931194130432,923342,'草坪音乐节',NULL,NULL,'https://ar-travel-file.1jiaohu.com/resource/20260610/26f5dfb05136413abfed90bb496d65cc.jpg','','','',NULL,'<p>校各单位：</p><p>根据《中共山西省委宣传部山西省科学技术协会山西省科学技术厅关于开展2026年“山西最美科技工作者”学习宣传活动的通知》（附件）要求，我校开展2026年山西省“最美科技工作者”推荐工作，有关事项安排如下：</p><p>1、各单位根据文件要求自愿组织推荐，择优推荐不超过1名科技工作者参加遴选。</p><p>2、本次推荐面向基层。突出基层一线，注重选树青年科技工作者（45岁以下）典型，兼顾不同类别、年龄、性别的科技工作者（党外科技人员优先）。</p><p>3、工作单位：山西农业大学；推荐单位：山西省农学会；纪检意见由科研部统一办理。</p><p>4、各单位于7月10日前将候选人推荐表和汇总表Word版、盖章版汇总表发送至邮箱<a href=\"mailto:sxndxsjl@126.com\">sxndxsjl@126.com</a>。</p><p>联系人：王慧贤 李琦</p><p><br/></p><p><img src=\"https://ar-travel-file.1jiaohu.com/resource/20260610/ae98ee4950b140ae9c6e65f40fed30c5.jpg\" style=\"max-width:100%;\" contenteditable=\"false\" data-extentions-extra-ocr-id=\"b993da0ce4651f062bf40a4fcd1a9f68\"/></p>',1,1,'2026-06-10 17:30:30','37.423038,112.583703',NULL,NULL,0,NULL,0,0,NULL,1,'https://ar-travel-file.1jiaohu.com/resource/20260610/afad066c80e64c3f9c2d46829a2371b2.jpg','','',NULL,NULL,'Lawn Music Festival',NULL,NULL,NULL,NULL,'',NULL,0,0,'2026-06-10 17:30:29',1,'','',NULL,NULL),(819740936698597376,923342,'酷跑活动',NULL,NULL,'https://ar-travel-file.1jiaohu.com/resource/20260610/ea5461f9f66f4d43a1e6230e63fb26ab.jpg','','','',NULL,'<p><img src=\"https://ar-travel-file.1jiaohu.com/resource/20260610/774870430c2e45aba1e5e0ea6b431f93.jpg\" style=\"max-width:100%;\" contenteditable=\"false\" data-extentions-extra-ocr-id=\"dc49e7c3724b42221477712d554f6e6e\"/></p><p><br/></p><p>6月1日至3日，校党委常委、副校（院）长张富强率城乡建设学院党政领导，赴湖北省丹江口市中国南水北调集团江汉水网建设开发有限公司（以下简称集团公司）及相关工程现场，围绕“深化校企合作、拓展就业岗位、搭建产教平台”开展专题调研交流，实地感受南水北调“世纪工程”的建设脉搏，并与企业方在人才培养、技术攻关、学生实习就业等方面达成了多项合作共识。</p>',1,1,'2026-06-10 18:02:18','37.423038,112.583703',NULL,NULL,0,NULL,0,0,NULL,2,'https://ar-travel-file.1jiaohu.com/resource/20260610/05d042b6fe1a4180ab8121e6d5cc7ed9.jpg','',NULL,NULL,NULL,'Cool Run Activity',NULL,NULL,NULL,NULL,'',NULL,0,0,'2026-06-10 18:02:18',1,NULL,NULL,NULL,NULL);
/*!40000 ALTER TABLE `travel_module_detail` ENABLE KEYS */;
