INSERT INTO `travel_video` VALUES (727642056713048064,238797802266955776,727564528384217088,' 耕土耘心育桃李 科教融合开新篇-山西农业大','视频农大','https://ar-travel.1jiaohu.com/files/20250929/81803914-51a0-4be9-8eb4-6354504480acwps (8).png','https://ar-travel.1jiaohu.com/files/20250929/9af98bb4-5ff6-4725-81b4-37b7a4c5b35a耕土耘心育桃李 科教融合开新篇-山西农业大.mp4','2025-09-29 14:34:14','1',20,NULL,NULL,NULL,NULL,NULL),(727644444454817792,238797802266955776,NULL,'逐梦﹒青春','2018年招生宣传片','https://ar-travel.1jiaohu.com/files/20250929/63e3ceee-f163-4d12-a5cb-58f5bdac8963逐梦﹒青春.png','https://ar-travel.1jiaohu.com/files/20250929/6ac171c9-e1b8-4f30-a0ae-30ed0515cec0逐梦﹒青春.mp4','2025-09-29 14:43:43','1',4,NULL,NULL,NULL,NULL,NULL),(727675869434482688,238797802266955776,NULL,'白鹿原','白鹿原在山西农大取景地','https://ar-travel.1jiaohu.com/files/20250929/e03993d3-7f58-4e51-8e7a-e853fea37ed4wps (12).png','https://ar-travel.1jiaohu.com/files/20250929/8927526b-17c8-4240-95b5-da99f601cef2白鹿原在山西农大取景地，老戏骨何冰的戏份。非常喜欢的一部经典电视剧，推荐大家看看。 山西农业大学 白鹿原 何冰 雷佳音 那些年追过的剧 - 抖音.mp4','2025-09-29 16:48:36','1',6,NULL,NULL,NULL,NULL,NULL);
