DROP TABLE IF EXISTS `travel_views`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `travel_views` (
  `id` bigint NOT NULL COMMENT '主键',
  `user_id` bigint DEFAULT NULL COMMENT '用户id',
  `time` datetime DEFAULT NULL COMMENT '时间',
  `event_type` tinyint DEFAULT '1' COMMENT '事件类型：1-小程序访问',
  `source` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源标识：首页、搜索、分享等',
  `source_detail` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源补充说明',
  `page_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '页面标识',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

